// Stable keys preserve existing collections and the five ordinary / three gold rule.
export function installComboCards(pools){
 const edit=(id,key,name,describe)=>Object.assign(pools[id].find(c=>c.key===key),{name,describe});
 const powers={
 1:['霜矢封缄',r=>`每支冰箭先冻结目标 ${(.6+.3*r).toFixed(1)} 秒，再造成伤害。可供黑塔碎冰、丹恒暴击。`],
 2:['击破弱点',r=>`攻击冻结、触电、中毒、燃烧、减速或标记目标时必定暴击，造成 ${(2+.35*r).toFixed(2)} 倍伤害。冲锋同样生效。`],
 3:['点火协议',r=>`轨道炮命中附加 ${2+r} 秒燃烧，每秒 ${5*r} 伤害；与融冰蒸爆、卡芙卡引爆联动。`],
 4:['冰晶回旋',r=>`击中冻结目标时额外向附近 ${r+1} 名敌人散射冰屑，冻结 0.6 秒。配合碎冰斩杀可不断制造新冰封目标。`],
 5:['反击寒潮',r=>`穹的护盾承受攻击时，冻结穹周围 ${100+30*r} 范围内敌人 ${(.5+.3*r).toFixed(1)} 秒。`],
 6:['攻守药剂',r=>`每次治疗同时向敌人发射药弹，造成 ${20*r} 伤害并附加中毒、减速，满血时也会施放。`],
 7:['复合毒素',r=>`丝线同时施加触电和 ${2+r} 秒中毒标记；丹恒可据此暴击，晚安与睡颜可引爆多种异常。`],
 8:['雷罚传导',r=>`击中异常目标时，将一半伤害沿闪电传给附近最多 ${r+1} 名敌人。神君、刀光与近战均可触发。`],
 9:['弱点扫描',r=>`导弹给目标施加 ${2+r} 秒标记，使全队对其伤害提高 20%，并视为异常状态。`],
 10:['余火引线',r=>`火弹附加 ${2+r} 秒燃烧，每秒 ${5*r} 伤害。点燃目标可供卡芙卡引爆、丹恒暴击。`],
 11:['蝶印猎杀',r=>`镰刀和飞刃施加 ${2+r} 秒蝶印，使全队伤害提高 20%；队友击杀同样触发希儿的残影追击。`]
 };
 const ranges={
 1:['护盾协射',r=>`穹有护盾时，每轮追加 ${r} 支冰箭，继承冻结、弹射和冰爆。`],
 2:['风压扩散',r=>`击中异常目标时，将减速扩散到周围 ${90+25*r} 范围，制造后续暴击条件。`],
 3:['融冰蒸爆',r=>`炮击冻结目标时解除其冰封，并向周围 ${100+25*r} 范围造成 60% 伤害的蒸汽爆发。`],
 4:['吸附回旋',r=>`锤击时将周围 ${140+30*r} 范围的敌人拉近，集中给旋转大锤和冰屑处理。`],
 5:['冰镜反射',r=>`施放时清除附近 ${180+30*r} 范围敌方弹丸，每清除一枚就向敌人反射一支冰箭。`],
 6:['解毒回流',r=>`队伍击败中毒敌人时，穹恢复 ${2*r} 点生命。与自身药弹、主角毒弹和卡芙卡配合。`],
 7:['疫病接力',r=>`异常敌人死亡时，将触电及其已有的中毒、燃烧扩散给附近最多 ${r+1} 名敌人，范围 ${170+30*r}。`],
 8:['神君震慑',r=>`神君和刀光命中时施加 ${.5+.5*r} 秒减速，为后续雷罚传导和丹恒暴击创造条件。`],
 9:['贯穿协议',r=>`每枚导弹命中后可继续追踪额外 ${r} 名敌人，继承标记和爆炸。`],
 10:['燎原',r=>`施放时，让附近燃烧敌人点燃其周围 ${65+15*r} 范围的敌人，持续 2 秒。`],
 11:['跨影寻猎',r=>`队伍击杀触发的残影可搜索 ${500+80*r} 范围的新目标，便于跨怪群接力。`]
 };
 for(let id=1;id<=11;id++){
  const [pn,pd]=powers[id];edit(id,'power',pn,r=>pd(r)+` 技能伤害／治疗／护盾额外 +${25*r}%。`);
  const [rn,rd]=ranges[id];edit(id,'range',rn,r=>rd(r)+` 技能范围额外 +${20*r}%。`);
  edit(id,'haste',id===4?'转转接力':'异常接力',r=>`队伍每击败一个异常敌人，自身技能冷却立即减少 ${(.15*r).toFixed(2)} 秒；被动冷却缩短 ${12*r}%。${id===4?`旋转和移动速度额外 +${20*r}%。`:''}`);
 }
 edit(4,'iceBurst','冰封终结',r=>`大锤命中已冻结的普通或精英敌人时直接碎冰斩杀；BOSS 不会被斩杀，改为 ${2+r} 倍碎冰伤害。另保留冰爆，半径 ${110+20*r}，伤害 ${75*r}%。`);
 edit(4,'frostWake','碎冰传染',r=>`附近被冻结的敌人死亡时，将冰冻传给其周围 ${85+25*r} 范围敌人，持续 ${(.6+.3*r).toFixed(1)} 秒。大锤仍留下 ${2+r} 秒冰原，冰原持续冻结。`);
 edit(2,'windWake','游龙不息',r=>`出枪后高速直线冲锋；丹恒每次击杀都自动衔接下一次冲锋（索敌 1000、单段最远 700），只要继续杀敌就可持续连冲。冲锋继承异常暴击；初次冲锋伤害 ${120*r}%。`);
 edit(11,'reprise','再现 · 影之接力',r=>`队友击杀也会召来残影，追斩附近敌人，造成技能 ${45+25*r}% 伤害。残影击杀还能再次触发残影，每条链最多 ${1+r} 段；不同击杀可开启新链。`);
 edit(5,'iceBurst','永冬降临',r=>`施放时冻结镜头内全部敌人 ${1.5+.75*r} 秒；BOSS 仅攻击间隔延长 20%，不能被碎冰秒杀。保留身周 ${130+25*r} 范围冰爆，造成 ${150*r}% 技能伤害。`);
 edit(7,'detonate','晚安与睡颜',r=>`丝线结算剩余触电伤害，并引爆额外异常：中毒／燃烧各计 20 基础伤害，冻结计 15，再乘 ${75*r}%。不消耗异常，可接暴击与碎冰。`);
}
export const COMBO_GUIDE={
 1:'扇形冰箭冻结＋环冰卫星补盾，再用普通牌护盾协射补箭，交给黑塔碎冰。',
 2:'八方风刃贯穿敌群＋游龙长驱连杀冲锋；异常暴击和万枪归阵共同收割密集敌群。',
 3:'点火协议＋融冰蒸爆：对冻结目标轰击触发蒸爆，燃烧又可被卡芙卡引爆。',
 4:'冰封裁决＋冰封传染＋超巨锤陀螺：队友铺冰，大锤斩杀，再把冰传给下一群。',
 5:'永冬降临冻结敌人＋苍穹堡垒保人；反击寒潮与三月七护盾协射组成防守连锁。',
 6:'生命回流弹命中回血，毒素连射施加中毒；搭配解毒回流，队友击杀中毒敌人也能恢复生命。',
 7:'复合毒素＋疫病接力＋异常交响：异常扩散、反复引爆，同时供丹恒暴击。',
 8:'全军神剑在全队脚下同步斩击一次，神君轮斩护住近身，万剑雷狱封住远处怪群。',
 9:'巨械守望部署巨型史瓦罗，饱和天幕连续轰炸；最终协议在机甲退场或重新部署时自爆清场。',
 10:'余火引线＋燎原＋流星暴雨：多弹点燃，燃烧扩散，交给卡芙卡引爆。',
 11:'死蝶收割吸魂增加移速与攻速；幻影军势让全队参与斩击，再用彼岸镰轮清理近身敌人。'
};
